// Vendors the ascii.rest pieces the page plays into src/vendor/ascii.gen.mjs (a string of minified JS the Worker inlines
// in the page's one nonce'd script: the CSP allows no other script). Run `npm run demo:vendor` after changing entry.js
// or a piece, and commit the result. ascii.rest is MIT (see ascii.rest.LICENSE); its notice is kept at the top of the output.
import { build } from "esbuild";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const licence = readFileSync(here("ascii.rest.LICENSE"), "utf8").trim();
const { outputFiles } = await build({
  entryPoints: [here("entry.js")],
  bundle: true,
  minify: true,
  format: "iife",
  globalName: "ASCII",
  target: "es2020",
  write: false,
  legalComments: "none",
});
const code = `/* Pieces and mount() from ascii.rest 0.4.0 (https://ascii.rest), MIT.\n${licence.replace(/\*\//g, "* /")}\n*/\n${outputFiles[0].text}`;
const out = `// Generated by demo/vendor/build.mjs from ascii.rest. Do not edit; run \`npm run demo:vendor\`.\nexport const ASCII_JS = ${JSON.stringify(code)};\n`;
writeFileSync(here("../src/vendor/ascii.gen.mjs"), out);
console.log(`ascii.gen.mjs: ${(code.length / 1024).toFixed(1)} KB of JS`);
